package app.canada.walmart;
import android.app.*;import android.content.*;import android.os.Build;import android.view.*;import android.widget.*;import java.util.*;import java.math.*;

final class ToolsPanel {
 static final String VERSION="1.6.0-beta.1";
 static void show(Context c){
  LinearLayout box=ToolUi.column(c);
  ToolUi.note(box,"Walmart Canada · Your shopping tools");
  ToolUi.action(box,"Stock checker","See supplied quantities by fulfilment option",android.R.drawable.ic_menu_search,()->StockPanel.show(c));
  ToolUi.action(box,"Scan barcode","Open Walmart’s product scanner",android.R.drawable.ic_menu_camera,()->{scan(c);ToolUi.close(c);});
  ToolUi.action(box,"Price history",HistoryStore.keys(c).size()+" saved products · prices and trends",android.R.drawable.ic_menu_recent_history,()->HistoryTools.browse(c,false));
  ToolUi.section(box,"More tools");
  ToolUi.action(box,"Shopping tools","Unit prices, basket calculator and checklist export",android.R.drawable.ic_menu_sort_by_size,()->shopping(c));
  ToolUi.action(box,"Settings","Ads, price recording and checklist preferences",android.R.drawable.ic_menu_preferences,()->controls(c));
  ToolUi.action(box,"Backup & export","Save, restore or manage your price history",android.R.drawable.ic_menu_save,()->backups(c));
  ToolUi.action(box,"Help & diagnostics","Feature guide and installed patches",android.R.drawable.ic_menu_help,()->help(c));
  ToolUi.home(c,"Patch tools",box);
 }
 static void help(Context c){LinearLayout box=ToolUi.column(c);ToolUi.note(box,"Walmart "+RuntimeCompatibility.appVersion()+" · tools "+VERSION);ToolUi.button(box,"Feature guide",()->ToolUi.message(c,"Feature guide","Stock checker: open a product through Walmart search or its scanner, then return to see supplied quantities. Store, pickup, delivery and shipping are labelled separately. Counts are read from product responses and may be absent or cached. Order limits are never used as stock. No watchlist or alerts.\n\nPrice history: records exact prices you view. No older archive or background monitoring. Existing favourites and target prices remain inside Price history.\n\nShopping: checklist exports need a loaded checklist. Calculators use amounts you enter.\n\nSettings apply only to patches selected when the APK was built. Back up histories before uninstalling or clearing app data."));ToolUi.button(box,"Diagnostics and installed patches",()->diagnostics(c));ToolUi.dialog(c,"Help & diagnostics",box);}
 static void toggle(LinearLayout box,String label,boolean value,android.widget.CompoundButton.OnCheckedChangeListener action){Switch s=new Switch(box.getContext());s.setText(label);s.setTextSize(16);s.setMinHeight(ToolUi.dp(s.getContext(),52));s.setChecked(value);box.addView(s,new LinearLayout.LayoutParams(-1,-2));s.setOnCheckedChangeListener((b,on)->{try{action.onCheckedChanged(b,on);}catch(Exception e){RuntimeStats.error(label,e);ToolUi.message(box.getContext(),"Control unavailable","The setting could not be fully applied. Reopen the screen and check diagnostics.");}});}
 static void setting(LinearLayout box,String label,String key,boolean ads){Context c=box.getContext();toggle(box,label,ToolSettings.enabled(c,key),(b,on)->{ToolSettings.set(c,key,on);if(ads)AdCleaner.refresh();});}
 static Activity activity(Context c){for(int i=0;i<10&&c!=null;i++){if(c instanceof Activity)return(Activity)c;if(!(c instanceof ContextWrapper))break;Context next=((ContextWrapper)c).getBaseContext();if(next==c)break;c=next;}return null;}
 static void controls(Context c){LinearLayout box=ToolUi.column(c);
  if(PatchStatus.installed.contains("Hide Ads and Sponsored Content")){ToolUi.text(box,"Advertising",18);setting(box,"Hide banner and carousel ads","hide_ads",true);setting(box,"Hide sponsored product cards","hide_sponsored",true);}else ToolUi.text(box,"Ad-hiding patch is not installed in this APK.",14);
  if(PatchStatus.installed.contains("Personal Price History")){ToolUi.text(box,"Price recording",18);setting(box,"Record prices (master switch)","record",false);setting(box,"Record shopping-list prices","record_lists",false);setting(box,"Record search and browse prices","record_browse",false);ToolUi.text(box,"Saved histories remain available while recording is paused. Reopen the product/list screen to refresh its labels.",14);}
  if(PatchStatus.installed.contains("Shopping Mode")){SharedPreferences prefs=c.getSharedPreferences("morphe_canada_shopping_v1",Context.MODE_PRIVATE);ToolUi.text(box,"Checklist",18);toggle(box,"Shopping mode · awake screen and larger targets",prefs.getBoolean("enabled",true),(b,on)->{prefs.edit().putBoolean("enabled",on).apply();Activity a=activity(c);if(a!=null)ShoppingMode.refreshSettings(a.getWindow().getDecorView());});toggle(box,"Show collected items",prefs.getBoolean("show_collected",false),(b,on)->{prefs.edit().putBoolean("show_collected",on).apply();Activity a=activity(c);if(a!=null)ShoppingMode.refreshSettings(a.getWindow().getDecorView());});}
  ToolUi.button(box,"Restore tool settings",()->ToolUi.confirm(c,"Restore defaults?","Ad hiding and recording will be enabled. Shopping mode will be enabled and collected rows hidden. Price history, favourites and targets are kept.",()->{ToolSettings.prefs(c).edit().clear().apply();c.getSharedPreferences("morphe_canada_shopping_v1",Context.MODE_PRIVATE).edit().clear().apply();AdCleaner.refresh();Activity a=activity(c);if(a!=null)ShoppingMode.refreshSettings(a.getWindow().getDecorView());ToolUi.message(c,"Defaults restored","Close and reopen Patch controls to see the updated switches.");}));ToolUi.dialog(c,"Patch controls",box);
 }
 static void shopping(Context c){LinearLayout box=ToolUi.column(c);ToolUi.button(box,"Scan a barcode",()->scan(c));ToolUi.button(box,"Compare unit prices",()->compare(c));ToolUi.button(box,"Basket / discount / tax calculator",()->calculator(c));ToolUi.button(box,"Copy loaded checklist",()->checklist(c,false));ToolUi.button(box,"Export loaded checklist as CSV",()->checklist(c,true));ToolUi.dialog(c,"Shopping tools",box);}
 static void scan(Context c){try{Intent i=new Intent().setClassName(c.getPackageName(),"com.walmart.glass.globalscanner.views.GlobalScannerActivity").putExtra("extraIncludeAllHandlers",true).putExtra("extraClient","lists");c.startActivity(i);RuntimeStats.hit("Scanner opened from tools");}catch(RuntimeException e){RuntimeStats.error("Scanner",e);ToolUi.message(c,"Scanner unavailable","The native scanner could not open.");}}
 static void compare(Context c){LinearLayout box=ToolUi.column(c);ToolUi.text(box,"Compare two offers using price, quantity per pack and pack count. Match measurement types; quality and checkout discounts are not compared.",14);EditText[] p=new EditText[2],size=new EditText[2],packs=new EditText[2];Spinner[] units=new Spinner[2];String[] labels={"g","kg","mL","L","each"};for(int i=0;i<2;i++){ToolUi.text(box,i==0?"Offer A":"Offer B",18);p[i]=ToolUi.input(box,"Total price CAD",true);size[i]=ToolUi.input(box,"Quantity per pack",true);packs[i]=ToolUi.input(box,"Number of packs",true);packs[i].setText("1");units[i]=new Spinner(c);units[i].setAdapter(new ArrayAdapter<String>(c,android.R.layout.simple_spinner_dropdown_item,labels));box.addView(units[i]);}TextView result=ToolUi.text(box,"",17);
  ToolUi.button(box,"Compare",()->{try{int u=units[0].getSelectedItemPosition(),v=units[1].getSelectedItemPosition();if((u/2)!=(v/2))throw new IllegalArgumentException("Choose matching measurement types (weight, volume or each)");BigDecimal[] values=new BigDecimal[2];for(int i=0;i<2;i++){int unit=units[i].getSelectedItemPosition();BigDecimal qty=ShoppingMath.value(size[i].getText().toString()).multiply(new BigDecimal(unit==1||unit==3?1000:1));values[i]=ShoppingMath.perUnit(p[i].getText().toString(),qty.toPlainString(),packs[i].getText().toString()).multiply(new BigDecimal(unit==4?1:100));}String suffix=u==4?" / each":u<2?" / 100 g":" / 100 mL";int cmp=values[0].compareTo(values[1]);String winner=cmp==0?"Same unit price":cmp<0?"Offer A is cheaper":"Offer B is cheaper";BigDecimal high=values[0].max(values[1]),low=values[0].min(values[1]);if(high.signum()>0&&cmp!=0)winner+=" by "+high.subtract(low).multiply(new BigDecimal(100)).divide(high,1,RoundingMode.HALF_UP)+"%";result.setText("A: $"+values[0].setScale(3,RoundingMode.HALF_UP)+suffix+"\nB: $"+values[1].setScale(3,RoundingMode.HALF_UP)+suffix+"\n"+winner);}catch(Exception e){result.setText(e instanceof NumberFormatException?"Enter valid prices, quantities and pack counts.":e.getMessage());}});ToolUi.dialog(c,"Unit-price comparison",box);
 }
 static void calculator(Context c){LinearLayout box=ToolUi.column(c);ToolUi.text(box,"Manual estimate. Enter either a basket subtotal with quantity 1, or an item price and quantity. Tax is applied after the percentage discount; real checkout rules may differ.",14);EditText amount=ToolUi.input(box,"Subtotal / unit price CAD",true),quantity=ToolUi.input(box,"Quantity",true),discount=ToolUi.input(box,"Discount %",true),tax=ToolUi.input(box,"Tax % (enter your applicable rate)",true),budget=ToolUi.input(box,"Budget CAD (optional)",true);quantity.setText("1");discount.setText("0");tax.setText("0");TextView result=ToolUi.text(box,"",17);
  ToolUi.button(box,"Calculate",()->{try{BigDecimal total=ShoppingMath.total(amount.getText().toString(),quantity.getText().toString(),discount.getText().toString(),tax.getText().toString());String text="Estimated total: $"+total+" CAD";if(!budget.getText().toString().trim().isEmpty()){BigDecimal remaining=ShoppingMath.value(budget.getText().toString()).subtract(total).setScale(2,RoundingMode.HALF_UP);text+="\n"+(remaining.signum()<0?"Over budget: $":"Budget left: $")+remaining.abs();}result.setText(text);}catch(Exception e){result.setText("Enter valid nonnegative amounts; percentages must be 0–100.");}});ToolUi.dialog(c,"Basket calculator",box);
 }
 static void checklist(Context c,boolean csv){try{Activity a=activity(c);View root=a==null?null:a.getWindow().getDecorView();View list=root==null?null:ListEnhancements.id(root,"list_detail_recycler_view");if(list==null)throw new IllegalStateException();Object adapter=list.getClass().getMethod("getAdapter").invoke(list);List<Object> items=new ArrayList<>();ChecklistTools.rows(adapter,items);if(items.isEmpty())throw new IllegalStateException();ToolUi.export(c,csv?"Checklist CSV":"Checklist",ChecklistExport.render(items,csv));
 }catch(Exception e){ToolUi.message(c,"Open a checklist first","Open a shopping checklist and wait for items to load, then reopen Patch tools. Only loaded items can be exported.");}}
 static void backups(Context c){LinearLayout box=ToolUi.column(c);ToolUi.text(box,"Exports contain product names, store context and saved prices. Nothing is sent until you choose a destination in Android's share sheet.",14);ToolUi.button(box,"Export price history CSV",()->ToolUi.export(c,"Price history CSV",HistoryTransfer.csv(c)));ToolUi.button(box,"Back up history, favourites and targets",()->{try{ToolUi.export(c,"Price history backup JSON",HistoryTransfer.json(c));}catch(Exception e){ToolUi.message(c,"Backup unavailable",e.getMessage());}});ToolUi.button(box,"Restore / merge pasted backup",()->restore(c));ToolUi.button(box,"Delete all saved price histories",()->ToolUi.confirm(c,"Delete all history?","This removes all locally saved observations, favourites and targets. It does not change Walmart lists or orders.",()->{HistoryStore.data(c).edit().clear().apply();HistoryStore.meta(c).edit().clear().apply();ToolUi.message(c,"History deleted","Your Walmart lists and orders are unchanged.");}));ToolUi.dialog(c,"Backup and export",box);}
 static void restore(Context c){LinearLayout box=ToolUi.column(c);ToolUi.text(box,"Paste a JSON backup exported by Patch tools. Observations are merged by timestamp; existing observations win conflicts. Maximum 128 histories and 30 observations each.",14);EditText input=ToolUi.input(box,"Paste backup JSON",false);input.setSingleLine(false);input.setMinLines(5);input.setMaxLines(10);TextView result=ToolUi.text(box,"",14);ToolUi.button(box,"Validate and merge",()->{try{int n=HistoryTransfer.merge(c,input.getText().toString());result.setText("Merged "+n+" histories.");}catch(Exception e){result.setText("No changes made: "+e.getMessage());}});ToolUi.dialog(c,"Restore history",box);}
 static String report(Context c){StringBuilder b=new StringBuilder("Walmart Canada Patch Pack "+VERSION+"\nTarget: "+RuntimeCompatibility.appVersion()+"\nAndroid API: "+Build.VERSION.SDK_INT+"\n\nInstalled patches:\n");for(String s:PatchStatus.installed)b.append("• ").append(s).append('\n');b.append("\nSession activity:\n");for(Map.Entry<String,Integer> e:RuntimeStats.countSnapshot().entrySet())b.append(e.getKey()).append(": ").append(e.getValue()).append('\n');b.append("\nObserved errors:\n");for(Map.Entry<String,String> e:RuntimeStats.errorSnapshot().entrySet())b.append(e.getKey()).append(": ").append(e.getValue()).append('\n');b.append("\nSaved histories: ").append(HistoryStore.keys(c).size()).append("\nRecording enabled: ").append(ToolSettings.enabled(c,"record")).append("\n\nInstalled is not the same as exercised. Counters are local session activity, not a complete crash log. No account IDs, tokens or product details are included here.");return b.toString();}
 static void diagnostics(Context c){LinearLayout box=ToolUi.column(c);TextView status=ToolUi.text(box,report(c),14);status.setTextIsSelectable(true);ToolUi.button(box,"Refresh status",()->status.setText(report(c)));ToolUi.button(box,"Copy diagnostics",()->ToolUi.copy(c,"patch diagnostics",report(c)));ToolUi.button(box,"Reset session counters",()->{RuntimeStats.clear();status.setText(report(c));});ToolUi.dialog(c,"Diagnostics",box);}
}
